    "section": "25",
    "title": "Sentence in cases of conviction of several offences at one trial",
    "text": "Allows courts to impose concurrent or consecutive sentences for multiple offences in one trial, with limits on aggregate imprisonment (not exceeding 14 years or twice the court’s single-offence sentencing power) and treats consecutive sentences as a single sentence for appeal purposes. (Source: bare-act arrangement summary.)",
