    "title": "Mode of conferring powers",
    "text": "Specifies that the High Court or State Government can confer powers under the BNSS by naming individuals, designating offices, or specifying classes of officials, with such powers effective upon communication to the empowered person. (Source: bare-act arrangement summary.)",
