    "title": "Powers of officers appointed",
    "text": "Ensures that government officers vested with BNSS powers retain those powers when appointed to equal or higher offices in the same local area under the same State Government, unless the High Court or State Government directs otherwise. (Source: bare-act arrangement summary.)",
