    "text": "Allows successors-in-office to exercise the powers and duties of Judges or Magistrates, with the Chief Judicial Magistrate, District Magistrate, or Sessions Judge resolving any doubts about succession for Magistrates or Additional/Assistant Sessions Judges. (Source: bare-act arrangement summary.)",
