    "text": "Obliges individuals to report knowledge of specific serious offences (e.g., murder, kidnapping, robbery, counterfeiting) or their intended commission under listed BNS sections to a Magistrate or police officer, unless they have a reasonable excuse. Extends to extraterritorial acts that would be offences in India. (Source: bare-act arrangement summary.)",
