    "section": "34",
    "title": "Duty of officers employed in connection with affairs of a village to make certain report",
    "text": "Requires village officers and residents to report to the nearest Magistrate or police station information about stolen property receivers, suspected robbers or escaped convicts, non-bailable offences, suspicious deaths, or extraterritorial acts that would be serious offences in India, as well as matters specified by the District Magistrate. Defines “village,” “proclaimed offender,” and “village officers” for clarity. (Source: bare-act arrangement summary.)",
