    "section": "7",
    "title": "Facts necessary to explain or introduce relevant facts",
    "text": "Allows facts that clarify, introduce, or contextualize relevant facts, such as identity, timing, or party relationships, to be admitted as necessary. (Source: bare-act arrangement summary.)",
