    "code": "BSA",
    "section": "8",
    "title": "Things said or done by conspirator in reference to common design",
    "text": "Makes statements or actions by co-conspirators relevant against all conspirators if done in furtherance of a common intention, provided a reasonable belief in the conspiracy exists. (Source: bare-act arrangement summary.)",
