    "section": "9",
    "title": "When facts not otherwise relevant become relevant",
    "text": "Permits otherwise irrelevant facts if they contradict or significantly affect the probability of facts in issue or relevant facts, such as alibis. (Source: bare-act arrangement summary.)",
