    "title": "Facts relevant when right or custom is in question",
    "text": "Specifies that transactions or instances related to the creation, claim, modification, recognition, assertion, denial, or inconsistency with a right or custom are relevant when its existence is questioned. (Source: bare-act arrangement summary.)",
