    "code": "BSA",
    "section": "13",
    "title": "Facts bearing on question whether act was accidental or intentional",
    "text": "Evidence of a series of similar acts by the same person is relevant to determine whether an act was accidental or intentional, or done with specific knowledge or intent. (Source: bare-act arrangement summary.)",
