    "code": "BSA",
    "section": "15",
    "title": "Admission defined",
    "text": "Defines an admission as a statement (oral, written, or electronic) that implies a fact in issue or relevant fact, made by specific persons under conditions outlined in subsequent sections. (Source: bare-act arrangement summary.)",
