    "code": "BSA",
    "section": "19",
    "title": "Proof of admissions against persons making them, and by or on their behalf",
    "text": "Admissions can be used against the maker or their representative but not by them, except when they would be admissible under Section 26 if the maker were dead, reflect a relevant state of mind or body with corroborating conduct, or are relevant for another purpose. (Source: bare-act arrangement summary.)",
    "punishment": "Evidentiary rule under Bharatiya Sakshya Adhiniyam, 2023.",
