    "code": "BSA",
    "section": "20",
    "title": "When oral admissions as to contents of documents are relevant",
    "text": "Oral admissions about a document’s contents are inadmissible unless the unless secondary evidence is permissible or the document’s authenticity is disputed. (Source: bare-act arrangement summary.)",
