    "id": "BSA-22",
    "code": "BSA",
    "section": "22",
    "title": "Confession caused by inducement, threat, coercion or promise, when irrelevant in criminal proceeding",
    "text": "Confessions obtained through inducement, threats, coercion, or promises from a person in authority are inadmissible in criminal proceedings if they suggest an advantage or avoidance of harm. Confessions made in police custody, if recorded immediately in writing or via audio-video means, are not considered coerced despite handcuffs. (Source: bare-act arrangement summary.)",
