    "section": "27",
    "title": "Relevancy of certain evidence for proving, in subsequent proceeding, the truth of facts therein stated",
    "text": "A criminal trial or inquiry shall be deemed to be a proceeding between the prosecutor and the accused within the meaning of this section. Explanation : Prior testimony from a judicial or authorized proceeding is admissible in later proceedings to prove stated facts if the witness is unavailable, provided the parties, issues, and cross-examination opportunities are substantially the same. (Source: bare-act arrangement summary.)",
    "punishment": "Evidentiary rule under Bharatiya Sakshya Adhiniyam, 2023.",
    "triggers": [
      "bsa 27",
      "bsa section 27",
      "section 27 bsa"
    ],
    "negTriggers": [],
