    "section": "28",
    "title": "Entries in books of account when relevant",
    "text": "Regularly maintained business account entries, including electronic records, are relevant but insufficient alone to establish liability. (Source: bare-act arrangement summary.)",
    "punishment": "Evidentiary rule under Bharatiya Sakshya Adhiniyam, 2023.",
