    "title": "Relevancy of statement as to fact of public nature contained in certain Acts or notifications",
    "text": "Statements about public facts in Central/State Acts, government notifications, or certain gazettes are relevant when the Court assesses such facts. (Source: bare-act arrangement summary.)",
