    "code": "BSA",
    "section": "36",
    "title": "Relevancy and effect of judgments, orders or decrees, other than those mentioned in section 35",
    "text": "Judgments outside Section 35’s scope are relevant for public matters but not conclusive proof of their contents. (Source: bare-act arrangement summary.)",
