    "title": "Judgments, etc., other than those mentioned in sections 34, 35 and 36, when relevant",
    "text": "Judgments not covered by Sections 34, 35, or 36 are irrelevant unless their existence is a fact in issue or relevant under another provision. (Source: bare-act arrangement summary.)",
