    "code": "BSA",
    "section": "38",
    "title": "Fraud or collusion in obtaining judgment, or incompetency of Court, may be proved",
    "text": "Parties can challenge relevant judgments under Sections 34, 35, or 36 by proving the Court lacked jurisdiction or the judgment was obtained fraudulently or collusively. (Source: bare-act arrangement summary.)",
