    "code": "BSA",
    "section": "39",
    "title": "Opinions of experts",
    "text": "Expert opinions on foreign law, science, art, handwriting, or fingerprints are relevant when the Court needs to form an opinion on these matters. (Source: bare-act arrangement summary.)",
