    "code": "BSA",
    "section": "43",
    "title": "Opinion as to usages, tenets, etc., when relevant",
    "text": "Opinions of those with specialized knowledge about group usages, religious/charitable institutions, or regional/class-specific terms are relevant. (Source: bare-act arrangement summary.)",
