    "code": "BSA",
    "section": "44",
    "title": "Opinion on relationship, when relevant",
    "text": "Opinions expressed through conduct by those with special knowledge (e.g., family members) about relationships are relevant, but insufficient alone to prove marriage in specific legal proceedings. (Source: bare-act arrangement summary.)",
