    "section": "50",
    "title": "Character as affecting damages",
    "text": "In sections 46, 47, 48 and this section, the word “character” includes both reputation and disposition; but, except as provided in section 48, evidence may be given only of general reputation and general disposition, and not of particular acts by which reputation or disposition were shown. Explanation : In civil cases, a person’s character (reputation and disposition) is relevant for assessing damages. Evidence is limited to general reputation/disposition, not specific acts, except as per Section 48. (Source: bare-act arrangement summary.)",
