    "section": "55",
    "title": "Oral evidence to be direct",
    "text": "Requires oral evidence to be direct, meaning it must come from a witness who personally saw, heard, or perceived the fact, or holds the opinion being presented, with provisions for expert treatises and material inspection. (Source: bare-act arrangement summary.)",
