    "code": "BSA",
    "section": "56",
    "title": "Proof of contents of documents",
    "text": "This section allows the contents of documents to be proved using either primary evidence (original documents) or secondary evidence (copies or other forms) as per the provisions of the Act. (Source: bare-act arrangement summary.)",
